import{_ as t,o as e,c as a,ag as o}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第64章 零点","description":"","frontmatter":{},"headers":[],"relativePath":"第64章_零点.md","filePath":"第64章_零点.md"}'),_={name:"第64章_零点.md"};function r(n,p,s,c,i,u){return e(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="第64章-零点" tabindex="-1">第64章 零点 <a class="header-anchor" href="#第64章-零点" aria-label="Permalink to &quot;第64章 零点&quot;">​</a></h1><p>我这四年没有在十一点以前睡过。</p><p>这件事我跟谁都没说过。</p><p>我跟她那边对出来的时间是：我这边零点，是她那边下午五点。</p><p>下午五点是她们一天里最乱的时候。</p><p>课刚上完，人要走去下一个地方，要么在公交上，要么在超市排队，要么在食堂找位置。</p><p>她一天里最不像她的话，全在那一个钟头。</p><p>我为什么知道她那时候最不像她。</p><p>因为那一个钟头她发的东西是碎的。</p><p>她会说：今天风好大。</p><p>然后过三分钟：我刚在车上差点坐过站。</p><p>再过两分钟：我这里有个男生在讲电话，讲得超大声音。</p><p>再过一分钟：啊不是，我在跟你说话，我在抱怨我自己的日子。</p><p>她说完了以后会补一句。</p><p>她说，我今天讲话好琐碎。</p><p>我说，挺好的。</p><p>她说，你听得下去？</p><p>我说，我这边十二点，我什么都不用干。</p><p>我这边十二点确实什么都不用干。</p><p>宿舍熄灯，屋子安静，呼噜起来了，郑拓的键盘也停了。</p><p>整个世界只有我这边一个人醒着，而那个醒着的人正在听一个下午五点的人讲她今天差点坐过站。</p><p>我算过一次。</p><p>我从大一九月熬到大二六月，两个学期。</p><p>按每晚平均多醒一小时四十分钟算，除掉寒暑假，在校天数大约二百二十天。</p><p>二百二十乘以一百分钟。</p><p>三百六十多个小时。</p><p>我把这个数写在本子上，写完自己看着想笑。</p><p>三百六十个小时。</p><p>一个人可以拿三百六十个小时学一门语言，练一项技术，考一张证。</p><p>我拿它换来听一个人说“今天风好大”。</p><p>而且这笔账没人能跟我算。</p><p>它不占我任何一张单子，不出现任何一次，没有一个地方能写“我为了一个人熬了三百六十小时”。</p><p>它只存在于一个我从不给人看的本子里。</p><p>而且她不知道。</p><p>她一直以为我晚上本来就不睡。</p><p>有一次她问我。</p><p>她说，你为什么每天这个时候都在。</p><p>我说，我刚好没睡。</p><p>她说，你天天刚好？</p><p>我说，我睡眠差。</p><p>她说，那你去看医生。</p><p>我说，不用。</p><p>她说，你这个人，你什么都&quot;不用&quot;。</p><p>那天我撒了谎。</p><p>我撒的是一个不需要任何 effort 的谎：我说我睡眠差。</p><p>她信了。</p><p>她信了以后开始替我想办法。</p><p>她去问她那边的同学，问失眠怎么办。</p><p>同学告诉她：睡前不要看屏幕，喝一点牛奶，把窗帘拉上。</p><p>她把这三条原样抄给我。</p><p>她说，你今晚试试。</p><p>我说，好。</p><p>她说，你试了要告诉我。</p><p>我说，好。</p><p>我那天晚上十点四十分把手机扣下了，闭着眼躺了半小时。</p><p>我没睡着。</p><p>十一点二十我又拿起来，给她发了一条。</p><p>我说，试了，不管用。</p><p>她说，那你明天再试。</p><p>我说，好。</p><p>我撒这个谎的代价是，她那天晚上也很高兴。</p><p>因为她第一次觉得自己为我做了一件具体的事。</p><p>我这边十二点，她那边下午五点，她拿着&quot;我教他怎么睡觉&quot;这一件小事，过了她那一个下午。</p><p>二月有一天夜里，我真熬不住了。</p><p>那天我发了一场低烧，三十八度二，我吃完药躺下，十点四十就没了意识。</p><p>她那边下午五点上线，说了四十分钟。</p><p>她说了：她在超市里因为一包米跟人挤了一下；她说她那天忘了带伞，在楼下站了十五分钟；她说她收到一封信，是她家里寄的，她没拆。</p><p>她说最后那句的时候，语气忽然变了。</p><p>她说，我今天不想讲这个，我先去上课。</p><p>她说，晚安。</p><p>她那边是下午五点四十说的晚安。</p><p>我第二天早上七点醒，烧退了，看见那四十分钟。</p><p>我一条一条回。</p><p>我回得很认真。</p><p>回完我看了一眼时间，我这边七点四十，她那边夜里十二点四十。</p><p>她睡了。</p><p>我等到了她那边下午五点。</p><p>她说，你昨天怎么没在。</p><p>我说，我睡了。</p><p>她说，你从来不睡。</p><p>我说，昨天吃了药。</p><p>她隔了很久。</p><p>然后她说了一句我那天真正难受的话。</p><p>她说，你不会是为了等我，才每天熬到十二点吧。</p><p>我说，不是。</p><p>她说，真的？</p><p>我说，真的，我本来就这个点睡。</p><p>她说，那你昨天十点四十就没了。</p><p>我说，我发烧。</p><p>她说，你发烧了你不跟我说。</p><p>我说，跟你说了你那边也是凌晨。</p><p>她说，我他妈在跟你说话。</p><p>我看到这一句，愣住了。</p><p>她说脏话的时候很少。</p><p>她说：我他妈在跟你说话。</p><p>意思是：你现在正在跟我讲话，你为什么不说。</p><p>我说，我怕你那晚上要上课。</p><p>她说，我不上课。</p><p>她说，我那天下午两点就没课了。</p><p>她说，我为了跟你说话推了一次小组。</p><p>我坐在那儿，一句话说不出来。</p><p>我推掉的那些晚上，她推掉的那些下午，我们两个从来没有碰在一起过。</p><p>我们两个都在为对方不出现在对方的时间里。</p><p>那天晚上她说了一句。</p><p>她说，你以后别熬了，我会内疚。</p><p>我说，好。</p><p>她说，你说得那么快，你肯定还会熬。</p><p>我说，我尽量。</p><p>她说，行，那我以后也在十二点以后不上。</p><p>我说，你别，你那边是下午。</p><p>她说，那我也不上。</p><p>她说，我们两个就都在吃饭的时候不聊天。</p><p>我说，你别这样。</p><p>她说，为什么。</p><p>我说，因为那正好是你最难的时候。</p><p>她说，你怎么知道我下午五点最难。</p><p>我说，因为你所有&quot;今天差点坐过站&quot;都是这个点说的。</p><p>她没回。</p><p>过了很久，她发了一句。</p><p>她说，你连这个都记得。</p><p>那天以后我做了一件事。</p><p>我开始写草稿。</p><p>我把我那天想跟她说的话，先打在手机的一个备忘录里。</p><p>不发送，只存着。</p><p>存到周六晚上十一点，我打开那个备忘录，一条一条挑。</p><p>挑出来发给她的那几条，叫&quot;能说的&quot;。</p><p>剩下那一大段，我自己留着。</p><p>那天晚上我在那个备忘录的第一行写了一句话。</p><p>我写：这里存的是她那边下午五点我没说的话。</p><p>那年我十七次打开那个备忘录。</p><p>一次也没有全发出去。</p>',131)])])}const f=t(_,[["render",r]]);export{l as __pageData,f as default};
